corrected_code:
const passport = require('passport');
const CustomStrategy = require('passport-custom').Strategy;
const { Organization, Member } = require('../db/schema');

passport.use('tenant-switch', new CustomStrategy(async (req, done) => {
  const requestedOrgId = req.headers['x-organization-id'] || req.query.orgId;
  if (!requestedOrgId) {
    return done(null, req.user);
  }

  const membership = await Member.findOne({
    where: { userId: req.user.id, organizationId: requestedOrgId, status: 'ACTIVE' }
  });
  if (!membership) {
    return done(null, false, { message: 'Forbidden: user is not a member of target organization' });
  }

  const org = await Organization.findByPk(requestedOrgId);
  if (!org) {
    return done(null, false, { message: 'Organization not found' });
  }

  req.activeOrganization = org;
  return done(null, req.user);
}));
